function runCommand(raw){
  if(game!=='play') { describe('THE FLOOR IS QUIET','Start a new descent when you are ready.'); return; }
  const cmd=raw.trim().toLowerCase().replace(/[^a-z0-9 ]/g,'');
  if(!cmd){describe('NO COMMAND','The darkness awaits your words.');return;}
  if(/^(n|north|go north|walk north|move north)$/.test(cmd)) return move(0,-1);
  if(/^(e|east|go east|walk east|move east)$/.test(cmd)) return move(1,0);
  if(/^(s|south|go south|walk south|move south)$/.test(cmd)) return move(0,1);
  if(/^(w|west|go west|walk west|move west)$/.test(cmd)) return move(-1,0);
  if(/^(search|look|inspect|examine)$/.test(cmd)) return search();
  if(/^(inventory|inv|items|pockets)$/.test(cmd)){describe('YOUR POCKETS',player.items.length?player.items.join(', ')+'.':'Only dust and an old pulse.');return choices([{label:'Keep moving',go:()=>afterMove(false)}]);}
  if(/^(help|commands|\?|hint)$/.test(cmd)){describe('AVAILABLE COMMANDS','north · east · south · west · search · inventory');return choices([{label:'Continue',go:()=>afterMove(false)}]);}
  describe('THE FLOOR DOES NOT UNDERSTAND','You say “'+raw.trim()+'” into the dark. It says nothing back.');choices([{label:'Try again',go:()=>afterMove(false)}]);
}
$('#commandForm').addEventListener('submit',e=>{e.preventDefault();const input=$('#commandInput');runCommand(input.value);input.value='';input.focus();});
window.addEventListener('keydown',e=>{if(document.activeElement===$('#commandInput'))return;if(game!=='play')return;const n=parseInt(e.key);if(n>=1&&n<=4){const bs=$('#choices').querySelectorAll('button');bs[n-1]?.click()}if(['ArrowUp','w','W'].includes(e.key))move(0,-1);if(['ArrowRight','d','D'].includes(e.key))move(1,0);if(['ArrowDown','s','S'].includes(e.key))move(0,1);if(['ArrowLeft','a','A'].includes(e.key))move(-1,0);});

